[
    {
        "title": "观察方程组",
        "description": "先观察两个方程：$x+y=7$，$2x-y=5$。因为第一个方程里 $y$ 的系数是 $1$，适合先把 $y$ 单独表示出来。",
        "bubbleText": "我们先挑一个最容易“变形”的式子。①里 $y$ 前面没有麻烦的系数，所以从它下手最省力。",
        "bubblePos": {
            "x": 300,
            "y": 170
        }
    },
    {
        "title": "由①表示y",
        "description": "由 $x+y=7$ 可得：$y=7-x$。",
        "bubbleText": "把①里的 $x$ 移到右边，$y$ 就被单独留下了：$y=7-x$。这一步是在给 $y$ 找一个“替身”。",
        "bubblePos": {
            "x": 540,
            "y": 140
        }
    },
    {
        "title": "代入第二个方程",
        "description": "把 $y=7-x$ 代入方程 $2x-y=5$，得到：$2x-(7-x)=5$。",
        "bubbleText": "现在看到 $y$，就用 $7-x$ 替换它。这样原来的二元问题，就慢慢变成一元问题了。",
        "bubblePos": {
            "x": 530,
            "y": 270
        }
    },
    {
        "title": "化简求x",
        "description": "化简：$2x-(7-x)=5$，先去括号得 $2x-7+x=5$，合并同类项得 $3x=12$。",
        "bubbleText": "减号遇到括号要特别小心，$-(7-x)$ 变成 $-7+x$。然后把同类的 $x$ 合在一起，就得到 $3x=12$。",
        "bubblePos": {
            "x": 535,
            "y": 405
        }
    },
    {
        "title": "解出x",
        "description": "由 $3x=12$，两边同时除以 $3$，得 $x=4$。",
        "bubbleText": "这一步很直接：$12$ 平均分成 $3$ 份，每份是 $4$，所以 $x=4$。",
        "bubblePos": {
            "x": 555,
            "y": 500
        }
    },
    {
        "title": "回代求y",
        "description": "把 $x=4$ 代回方程 $x+y=7$：$4+y=7$，所以 $y=3$。",
        "bubbleText": "已经知道 $x$ 了，就把它放回原方程。离 $7$ 还差 $3$，所以 $y=3$。",
        "bubblePos": {
            "x": 220,
            "y": 380
        }
    },
    {
        "title": "验算答案",
        "description": "检验：代入①，$4+3=7$，成立；代入②，$2\\times4-3=8-3=5$，也成立。所以方程组的解是 $\\begin{cases}x=4\\\\y=3\\end{cases}$。",
        "bubbleText": "最后一定要验算。两个方程都对，才说明我们真的找到了同一组答案：$x=4$，$y=3$。",
        "bubblePos": {
            "x": 520,
            "y": 210
        }
    }
]
